CREATE OR REPLACE FUNCTION public.guard_reward_timezone() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.axen_is_server_write() THEN IF TG_OP='UPDATE' THEN NEW.reward_timezone:=OLD.reward_timezone; ELSE NEW.reward_timezone:='Asia/Kolkata'; END IF; END IF; IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.reward_timezone) THEN RAISE EXCEPTION 'invalid stored timezone'; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.complete_zen_session(_session_id uuid) RETURNS TABLE(coins integer,awarded integer,minutes integer,result text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); s public.focus_sessions; lifecycle text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74010)); lifecycle:=public.zen_reward_progress(_session_id,'ping'); SELECT * INTO s FROM public.focus_sessions WHERE id=_session_id AND user_id=u FOR UPDATE; SELECT p.coins INTO coins FROM public.profiles p WHERE p.id=u; minutes:=s.minutes; awarded:=0; IF lifecycle='completed' THEN result:='already_completed'; RETURN NEXT; RETURN; END IF; IF lifecycle<>'running' OR now()-s.started_at < make_interval(secs=>s.duration_seconds) OR s.reward_active_seconds<s.duration_seconds THEN UPDATE public.focus_sessions SET reward_lifecycle='cancelled',ended_at=now() WHERE id=s.id; result:='not_eligible'; RETURN NEXT; RETURN; END IF; awarded:=public.axen_award_completion_coins(u,'zen',s.id); UPDATE public.focus_sessions SET reward_lifecycle='completed',ended_at=now(),coins_awarded=awarded WHERE id=s.id; SELECT p.coins INTO coins FROM public.profiles p WHERE p.id=u; result:=CASE WHEN awarded>0 THEN 'awarded' ELSE 'daily_claimed' END; RETURN NEXT; END; $$;